import numpy as np
def read(p):
    L=open(p).read().split('\n'); n=int(L[0]); els=[];xyz=[]
    for l in L[2:2+n]:
        q=l.split(); els.append(q[0]); xyz.append([float(x) for x in q[1:4]])
    return els, np.array(xyz)
els,P = read('opt1.xyz')
cov = {'H':0.31,'C':0.76,'O':0.66,'F':0.57,'Cr':1.39}
n=len(els)
D=np.linalg.norm(P[:,None]-P[None,:],axis=-1)
adj=[[] for _ in range(n)]
for i in range(n):
    for j in range(i+1,n):
        if D[i,j] < 1.25*(cov[els[i]]+cov[els[j]]):
            adj[i].append(j); adj[j].append(i)
# Cr environments
for c in [i for i,e in enumerate(els) if e=='Cr']:
    print("Cr",c,[(els[j],j,round(D[c,j],2)) for j in adj[c]])
# O environments
for o in [i for i,e in enumerate(els) if e=='O']:
    print("O",o,[(els[j],j) for j in adj[o]])
# C with F3: check CF3 groups
cf3=[i for i,e in enumerate(els) if e=='C' and sum(1 for j in adj[i] if els[j]=='F')==3]
print("CF3 carbons:", cf3)
# quaternary C bonded to O, CF3, phenyl, phenylene
for q in [i for i,e in enumerate(els) if e=='C' and len(adj[i])==4 and els[adj[i][0]]!='H' and els[adj[i][1]]!='H' and els[adj[i][2]]!='H' and els[adj[i][3]]!='H']:
    print("quatC",q,[(els[j],j) for j in adj[q]])
